<script setup>
import memberTemplate from './assets/member-template.xlsx?url';
import PagedRecords from './PagedRecords.vue';
import {s,canAdmin,run,previewMembers,importMembers,number} from './store';
</script><template><section class="card stack"><div class="toolbar"><h3>Thành viên</h3><div class="row"><a v-if="canAdmin" :href="memberTemplate" download="Mau-thanh-vien.xlsx" class="member-template-link">Tải file Excel mẫu</a><MButton variant="primary" v-if="canAdmin" @click="s.dialog='member'">Thêm thành viên</MButton></div></div><template v-if="canAdmin"><MUpload accept=".xlsx" :multiple="false" :max-size-m-b="10" :disabled="s.busy" label="Thêm thành viên bằng file Excel" @select-files="run(()=>previewMembers($event))" @oversized="s.error='File tối đa 10 MB.'" /><div v-if="s.memberPreview" class="stack"><p>{{number(s.memberPreview.rows.length)}} thành viên hợp lệ / {{number(s.memberPreview.total)}} dòng.</p><PagedRecords v-if="s.memberPreview.errors.length" :rows="s.memberPreview.errors" v-slot="{rows:pageRows}"><p v-for="e in pageRows" :key="e.row" class="error">Dòng {{e.row}}: {{e.message}}</p></PagedRecords><PagedRecords :rows="s.memberPreview.rows" v-slot="{rows:pageRows}"><div class="mobile-list"><article v-for="m in pageRows" :key="m.email">{{m.name}} · {{m.email}} · Editor</article></div></PagedRecords><div class="row justify-end"><MButton variant="secondary" @click="s.memberPreview=null">Hủy</MButton><MButton variant="primary" :disabled="!!s.memberPreview.errors.length||!s.memberPreview.rows.length" :loading="s.busy" @click="run(importMembers)">Xác nhận import</MButton></div></div></template></section></template>
